package com.tencent.weknora.model.client;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.docreader.GoUtf8;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.Consumer;

/** Native production Go Anthropic Messages protocol; capabilities come from the live catalog. */
public final class AnthropicMessages implements ChatModel {
    private static final ObjectMapper JSON=SafeModelHttp.JSON;
    private static final String BLOCKS="anthropic_thinking_blocks",REDACTED="anthropic_redacted_thinking",SIGNATURE="anthropic-messages:";
    private static final List<String> LADDER=List.of("minimal","low","medium","high","xhigh","max");
    private final SafeModelHttp http;private final ModelEndpoint endpoint;private final Duration chatTimeout,streamTimeout;
    public AnthropicMessages(SafeModelHttp http,ModelEndpoint endpoint,Duration chatTimeout,Duration streamTimeout){this.http=http;this.endpoint=endpoint;this.chatTimeout=chatTimeout;this.streamTimeout=streamTimeout;}
    @Override public String modelId(){return endpoint.id;}@Override public String modelName(){return endpoint.name;}
    private boolean flag(String key){return endpoint.settings.path(key).asBoolean();}
    private record Plan(boolean enabled,ObjectNode body,String effort,long budget){}
    private boolean supports(String level){return endpoint.thinking.has(level)?!endpoint.thinking.get(level).isNull():!Set.of("xhigh","max").contains(level);}
    private String clamp(String level){if(!LADDER.contains(level)||supports(level))return level;int at=LADDER.indexOf(level);for(int i=at+1;i<LADDER.size();i++)if(supports(LADDER.get(i)))return LADDER.get(i);for(int i=at-1;i>=0;i--)if(supports(LADDER.get(i)))return LADDER.get(i);return "auto";}
    private static String level(ObjectNode opts){if(opts==null)return "";String value=opts.path("reasoning_effort").asText();if(Set.of("none","false","disabled").contains(value))return "off";if(Set.of("true","enabled","default","on").contains(value))return "auto";if(value.equals("off")||value.equals("auto")||LADDER.contains(value))return value;return opts.hasNonNull("thinking")?(opts.path("thinking").asBoolean()?"auto":"off"):"";}
    private Plan plan(ObjectNode opts){String level=level(opts);if(level.isEmpty())return new Plan(false,null,"",0);level=clamp(level);boolean adaptive=endpoint.settings.path("thinking_mode").asText().equals("adaptive");if(level.equals("off"))return new Plan(false,supports("off")&&adaptive?JSON.createObjectNode().put("type","disabled"):null,"",0);if(adaptive){String effort=LADDER.contains(level)&&flag("supports_effort")?endpoint.thinking.path(level).asText(level):"";return new Plan(true,JSON.createObjectNode().put("type","adaptive"),effort,0);}long budget=opts==null?0:opts.path("thinking_budget_tokens").asLong();if(budget<=0)budget=endpoint.settings.path("thinking_budgets").path(LADDER.contains(level)?level:"medium").asLong();budget=Math.max(1024,budget);return new Plan(true,JSON.createObjectNode().put("type","enabled").put("budget_tokens",budget),"",budget);}
    public ObjectNode request(List<ObjectNode> messages,ObjectNode opts,boolean stream){
        Plan plan=plan(opts);ObjectNode body=JSON.createObjectNode().put("model",endpoint.wireModel);if(stream)body.put("stream",true);long max=opts==null?0:opts.path("max_completion_tokens").asLong();if(max<=0&&opts!=null)max=opts.path("max_tokens").asLong();if(max<=0)max=endpoint.settings.path("default_max_tokens").asLong();if(max<=0)max=4096;if(plan.budget>0&&max<=plan.budget)max=plan.budget+Math.max(max,1024);body.put("max_tokens",max);
        if(opts!=null){if(flag("supports_temperature")&&opts.path("temperature").asDouble()>0&&(!plan.enabled||flag("temperature_with_thinking")))body.set("temperature",opts.get("temperature"));else if(flag("supports_top_p")&&opts.path("top_p").asDouble()>0&&!plan.enabled)body.set("top_p",opts.get("top_p"));}
        String retention=opts==null?"":opts.path("cache_retention").asText();ObjectNode marker=null;if(flag("supports_cache_control")&&!retention.equals("none")){marker=JSON.createObjectNode().put("type","ephemeral");String ttl=endpoint.settings.path("long_cache_ttl").asText();if(retention.equals("long")&&!ttl.isEmpty())marker.put("ttl",ttl);}
        if(opts!=null&&!opts.path("tools").isEmpty()){ArrayNode tools=JSON.createArrayNode();for(JsonNode t:opts.path("tools")){JsonNode fn=t.path("function"),schema=fn.get("parameters");if(schema==null)schema=JSON.createObjectNode().put("type","object").set("properties",JSON.createObjectNode());tools.add(JSON.createObjectNode().put("name",fn.path("name").asText()).put("description",fn.path("description").asText()).set("input_schema",schema.deepCopy()));}if(marker!=null&&flag("supports_cache_control_on_tools"))((ObjectNode)tools.get(tools.size()-1)).set("cache_control",marker.deepCopy());body.set("tools",tools);String choice=opts.path("tool_choice").asText();String type=choice.equals("required")?"any":choice.equals("none")?"none":choice.isEmpty()||choice.equals("auto")?"auto":"tool";ObjectNode tc=JSON.createObjectNode().put("type",type);if(type.equals("tool")&&!choice.isEmpty())tc.put("name",choice);if(opts.hasNonNull("parallel_tool_calls")&&!type.equals("none"))tc.put("disable_parallel_tool_use",!opts.path("parallel_tool_calls").asBoolean());body.set("tool_choice",tc);}
        List<String> systems=new ArrayList<>();ArrayNode turns=JSON.createArrayNode();for(ObjectNode original:messages){String content=ModelText.trim(ModelText.neutralize(original.path("content").asText())),role=original.path("role").asText();switch(role){case "system":if(content.isEmpty())content=multiText(original);if(!content.isEmpty())systems.add(content);break;case "assistant":{ArrayNode blocks=replay(original);if(content.isEmpty())content=multiText(original);if(!content.isEmpty())blocks.add(textBlock(content));for(JsonNode call:original.path("tool_calls")){JsonNode input=parseArguments(ModelText.neutralize(call.path("function").path("arguments").asText()));ObjectNode b=JSON.createObjectNode().put("type","tool_use");put(b,"id",call.path("id").asText());put(b,"name",call.path("function").path("name").asText());b.set("input",input);blocks.add(b);}addTurn(turns,"assistant",blocks,original.path("tool_calls").isEmpty());break;}case "tool":{ObjectNode b=JSON.createObjectNode().put("type","tool_result");put(b,"tool_use_id",original.path("tool_call_id").asText());String output=ModelText.neutralize(original.path("content").asText());b.put("content",output);if(!turns.isEmpty()){ObjectNode last=(ObjectNode)turns.get(turns.size()-1);JsonNode blocks=last.path("content");if(last.path("role").asText().equals("user")&&blocks.isArray()&&!blocks.isEmpty()&&blocks.get(0).path("type").asText().equals("tool_result")){((ArrayNode)blocks).add(b);break;}}turns.add(JSON.createObjectNode().put("role","user").set("content",JSON.createArrayNode().add(b)));break;}default:addTurn(turns,"user",userBlocks(original,content),true);}}
        String system=String.join("\n\n",systems);if(!system.isEmpty())body.set("system",marker==null?TextNode.valueOf(system):JSON.createArrayNode().add(textBlock(system).set("cache_control",marker.deepCopy())));if(marker!=null&&!turns.isEmpty()){ObjectNode last=(ObjectNode)turns.get(turns.size()-1);JsonNode content=last.path("content");if(content.isTextual()&&!content.asText().isEmpty())last.set("content",JSON.createArrayNode().add(textBlock(content.asText()).set("cache_control",marker.deepCopy())));else if(content.isArray()&&!content.isEmpty())((ObjectNode)content.get(content.size()-1)).set("cache_control",marker.deepCopy());}body.set("messages",turns);if(plan.body!=null)body.set("thinking",plan.body);if(!plan.effort.isEmpty())body.set("output_config",JSON.createObjectNode().put("effort",plan.effort));endpoint.settings.path("extra_body").fields().forEachRemaining(e->{if(!body.has(e.getKey()))body.set(e.getKey(),e.getValue().deepCopy());});return body;
    }
    private static void addTurn(ArrayNode turns,String role,ArrayNode blocks,boolean flatten){if(blocks.isEmpty())return;JsonNode content=flatten&&blocks.size()==1&&blocks.get(0).path("type").asText().equals("text")?blocks.get(0).path("text"):blocks;turns.add(JSON.createObjectNode().put("role",role).set("content",content));}
    private static ObjectNode textBlock(String text){ObjectNode block=JSON.createObjectNode().put("type","text");put(block,"text",text);return block;}
    private static void put(ObjectNode obj,String key,String value){if(!value.isEmpty())obj.put(key,value);}
    private static String multiText(ObjectNode m){List<String> parts=new ArrayList<>();for(JsonNode p:m.path("multi_content"))if(p.path("type").asText().equals("text")){String value=ModelText.trim(ModelText.neutralize(p.path("text").asText()));if(!value.isEmpty())parts.add(value);}return String.join("\n",parts);}
    private static JsonNode parseArguments(String value){if(value.isEmpty())return JSON.createObjectNode();try{return JSON.reader().with(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).readTree(value);}catch(IOException ex){return JSON.createObjectNode();}}
    private static ArrayNode replay(ObjectNode m){ArrayNode blocks=JSON.createArrayNode();JsonNode stored=m.path("reasoning_metadata").get(BLOCKS);if(stored!=null&&(stored.isArray()||stored.isNull())){boolean valid=true;for(JsonNode b:stored)try{validateThinking(b);}catch(ModelClientException ex){valid=false;break;}if(valid){for(JsonNode b:stored){String type=text(b,"type");if(type.equals("thinking")&&!text(b,"signature").isEmpty())blocks.add(thinking(type,text(b,"thinking"),text(b,"signature"),""));else if(type.equals("redacted_thinking"))blocks.add(thinking(type,"","",text(b,"data")));}return blocks;}}
        JsonNode redacted=m.path("reasoning_metadata").get(REDACTED);if(redacted!=null&&redacted.isArray()){boolean valid=true;for(JsonNode b:redacted)if(!b.isNull()&&!b.isTextual())valid=false;if(valid)for(JsonNode b:redacted)blocks.add(thinking("redacted_thinking","","",b.isNull()?"":b.asText()));}String signature=m.path("reasoning_signature").asText(),content=ModelText.neutralize(m.path("reasoning_content").asText());if(signature.startsWith(SIGNATURE)&&!content.isEmpty()&&signature.length()>SIGNATURE.length())blocks.add(thinking("thinking",content,signature.substring(SIGNATURE.length()),""));return blocks;}
    private static ObjectNode thinking(String type,String content,String signature,String data){ObjectNode b=JSON.createObjectNode().put("type",type);put(b,"thinking",content);put(b,"signature",signature);put(b,"data",data);return b;}
    private static ArrayNode userBlocks(ObjectNode m,String content){ArrayNode parts=JSON.createArrayNode();if(!m.path("multi_content").isEmpty()){for(JsonNode p:m.path("multi_content")){if(p.path("type").asText().equals("text")){String text=ModelText.trim(ModelText.neutralize(p.path("text").asText()));if(!text.isEmpty())parts.add(textBlock(text));}else if(p.path("type").asText().equals("image_url")&&p.hasNonNull("image_url"))addImage(parts,p.path("image_url").path("url").asText());}}else for(JsonNode image:m.path("images"))addImage(parts,image.asText());if(!content.isEmpty())parts.add(textBlock(content));return parts;}
    private static void addImage(ArrayNode blocks,String ref){ObjectNode source=null;if(ref.startsWith("data:")){int at=ref.indexOf(";base64,");if(at<0)return;String media=ref.substring(5,at),data=ref.substring(at+8),plain=data.replace("\r","").replace("\n","");try{if(plain.length()%4!=0)return;Base64.getDecoder().decode(plain);}catch(IllegalArgumentException ex){return;}source=JSON.createObjectNode().put("type","base64");put(source,"media_type",media);put(source,"data",data);}else{if(ref.startsWith("resource://")||ref.startsWith("local://")||ref.startsWith("storage://"))throw new ModelClientException("Native chat requires an absolute HTTP or data image URL; storage image resolution is not migrated");try{String scheme=URI.create(ref).getScheme();if("http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme))source=JSON.createObjectNode().put("type","url").put("url",ref);else return;}catch(IllegalArgumentException ex){return;}}if(source!=null)blocks.add(JSON.createObjectNode().put("type","image").set("source",source));}
    public Map<String,String> headers(ObjectNode opts,boolean stream){Map<String,String> out=endpoint.headers(stream);String version=endpoint.settings.path("version").asText();out.put("anthropic-version",version.isEmpty()?"2023-06-01":version);LinkedHashSet<String> beta=new LinkedHashSet<>();for(JsonNode b:endpoint.settings.path("beta_headers"))addBeta(beta,b.asText());Plan p=plan(opts);if(p.enabled&&!endpoint.settings.path("thinking_mode").asText().equals("adaptive")&&opts!=null&&!opts.path("tools").isEmpty())addBeta(beta,endpoint.settings.path("interleaved_thinking_beta").asText());addBeta(beta,out.getOrDefault("anthropic-beta",""));if(!beta.isEmpty())out.put("anthropic-beta",String.join(",",beta));return out;}
    private static void addBeta(Set<String> beta,String value){for(String part:value.split(",",-1)){part=ModelText.trim(part);if(!part.isEmpty())beta.add(part);}}
    private SafeModelHttp.Response sendOnce(CallContext call,List<ObjectNode> messages,ObjectNode opts,boolean stream){Duration timeout=call.deadline()==null?(stream?streamTimeout:chatTimeout):Duration.ZERO;SafeModelHttp.Response response=http.post(call,endpoint.url,headers(opts,stream),request(messages,opts,stream).toString().getBytes(StandardCharsets.UTF_8),timeout);if(response.status()<200||response.status()>=300){try(response){throw new ModelHttpException(response.status(),response.text(1<<20),endpoint);}}return response;}
    private SafeModelHttp.Response send(CallContext call,List<ObjectNode> messages,ObjectNode opts,boolean stream){try{return sendOnce(call,messages,opts,stream);}catch(ModelHttpException ex){if(!ex.retryWithoutImages())throw ex;return sendOnce(call,ChatInputs.stripImages(messages),opts,stream);}}
    @Override public ObjectNode chat(CallContext call,List<ObjectNode> messages,ObjectNode opts){try(var response=send(call,messages,opts,false)){if(response.headers().getOrDefault("content-type","").toLowerCase(Locale.ROOT).contains("text/event-stream"))return collect(call,response.body());return decode(new ModelJsonSource(GoUtf8.decode(response.bytes(64<<20)),false));}catch(IOException ex){throw new ModelClientException("decode response: "+ex.getMessage());}}
    @Override public void stream(CallContext call,List<ObjectNode> messages,ObjectNode opts,Consumer<ObjectNode> consumer){try(var response=send(call,messages,opts,true)){process(call,response.body(),consumer);}}
    private static String text(JsonNode n,String k){JsonNode v=n==null?null:n.get(k);if(v==null||v.isNull())return "";if(!v.isTextual())throw new ModelClientException("decode response: "+k+" must be a string");return v.asText();}
    private static long integer(JsonNode n,String k){JsonNode v=n==null?null:n.get(k);if(v==null||v.isNull())return 0;if(!v.isIntegralNumber()||!v.canConvertToLong())throw new ModelClientException("decode response: "+k+" must be an integer");return v.asLong();}
    private static void object(JsonNode n,String label){if(n!=null&&!n.isNull()&&!n.isMissingNode()&&!n.isObject())throw new ModelClientException("decode "+label+": expected object");}
    private static void validateThinking(JsonNode n){object(n,"thinking block");for(String k:List.of("type","thinking","signature","data"))text(n,k);}
    private static void validateBlock(JsonNode n){object(n,"content block");for(String k:List.of("type","text","id","name","thinking","signature","data"))text(n,k);}
    private static void validateUsage(JsonNode n){object(n,"usage");for(String k:List.of("input_tokens","output_tokens","cache_creation_input_tokens","cache_read_input_tokens"))integer(n,k);}
    private static void validateError(JsonNode n){object(n,"error");text(n,"type");text(n,"message");}
    private ObjectNode usage(JsonNode n){validateUsage(n);long read=integer(n,"cache_read_input_tokens"),write=integer(n,"cache_creation_input_tokens"),prompt=integer(n,"input_tokens")+read+write,completion=integer(n,"output_tokens");boolean reported=n!=null&&(n.hasNonNull("cache_read_input_tokens")||n.hasNonNull("cache_creation_input_tokens"));return counters(prompt,completion,read,write,Math.max(0,prompt-read),reported,!reported&&!flag("prompt_cache_accounting"));}
    private static ObjectNode counters(long prompt,long completion,long read,long write,long miss,boolean reported,boolean unsupported){ObjectNode out=JSON.createObjectNode().put("prompt_tokens",prompt).put("completion_tokens",completion).put("total_tokens",prompt+completion);read=Math.max(0,read);write=Math.max(0,write);miss=Math.max(0,miss);if(!unsupported){if(read>0)out.put("cached_tokens",read).put("cache_read_tokens",read);if(write>0)out.put("cache_write_tokens",write);if(miss>0)out.put("cache_miss_tokens",miss);}return out.put("cache_reported",reported).put("cache_status",unsupported?"unsupported":!reported?"unreported":read>0?"hit":"miss");}
    private static String finish(String reason,int tools,boolean incomplete){if(incomplete||reason.isEmpty())return "incomplete";if(reason.equals("max_tokens"))return "length";if(reason.equals("tool_use")||tools>0&&reason.equals("end_turn"))return "tool_calls";return reason.equals("refusal")?"content_filter":reason;}
    ObjectNode decode(ModelJsonSource source){JsonNode n=source.root;object(n,"response");text(n,"type");text(n,"stop_reason");validateUsage(n.path("usage"));validateError(n.path("error"));JsonNode content=n.path("content");if(!content.isMissingNode()&&!content.isNull()&&!content.isArray())throw new ModelClientException("decode response: content must be an array");for(JsonNode b:content)validateBlock(b);String error=text(n.path("error"),"message");if(!error.isEmpty())throw new ModelClientException(endpoint.safe("API error: "+error));StringBuilder answer=new StringBuilder(),thought=new StringBuilder();String signature="";ArrayNode blocks=JSON.createArrayNode(),calls=JSON.createArrayNode();int index=0;for(JsonNode b:content){switch(text(b,"type")){case "text":answer.append(text(b,"text"));break;case "thinking":thought.append(text(b,"thinking"));blocks.add(thinking("thinking",text(b,"thinking"),text(b,"signature"),""));if(!text(b,"signature").isEmpty())signature=SIGNATURE+text(b,"signature");break;case "redacted_thinking":blocks.add(thinking("redacted_thinking","","",text(b,"data")));break;case "tool_use":String args=source.raw("/content/"+index+"/input");calls.add(tool(text(b,"id"),text(b,"name"),args.isEmpty()?"{}":args));break;}index++;}ObjectNode result=JSON.createObjectNode().put("content",answer.toString());put(result,"reasoning_content",thought.toString());put(result,"reasoning_signature",signature);if(!blocks.isEmpty())result.set("reasoning_metadata",JSON.createObjectNode().set(BLOCKS,blocks));if(!calls.isEmpty())result.set("tool_calls",calls);result.put("finish_reason",finish(text(n,"stop_reason"),calls.size(),false));result.set("usage",usage(n.path("usage")));return result;}
    private static ObjectNode tool(String id,String name,String args){return JSON.createObjectNode().put("id",id).put("type","function").set("function",JSON.createObjectNode().put("name",name).put("arguments",args));}
    private static final class ToolState {final String id,name,initial;final StringBuilder json=new StringBuilder();boolean closed;ToolState(String id,String name,String initial){this.id=id;this.name=name;this.initial=initial;}}
    private final class StreamState {
        final SortedMap<Long,ToolState> tools=new TreeMap<>();final List<Long> toolOrder=new ArrayList<>();final LinkedHashMap<Long,ObjectNode> thoughts=new LinkedHashMap<>();String signature="",stop="";ObjectNode usage;
        int toolIndex(long index){int at=toolOrder.indexOf(index);if(at>=0)return at;toolOrder.add(index);return toolOrder.size()-1;}
        ObjectNode thought(long index,String type){return thoughts.computeIfAbsent(index,k->JSON.createObjectNode().put("type",type));}
        ArrayNode calls(){ArrayNode out=JSON.createArrayNode();for(ToolState t:tools.values())if(t.closed)out.add(tool(t.id,t.name,t.json.isEmpty()?t.initial:t.json.toString()));return out;}
        boolean incomplete(){return tools.values().stream().anyMatch(t->!t.closed);}
        void consume(ModelJsonSource source,ModelStreamAssembler assembler){JsonNode event=source.root;if(event==null||event.isNull())return;object(event,"SSE response");String type=text(event,"type");long rawIndex=integer(event,"index");long index=rawIndex;JsonNode block=event.path("content_block"),delta=event.path("delta"),message=event.path("message");validateBlock(block);object(delta,"delta");for(String k:List.of("type","text","thinking","signature","stop_reason","partial_json"))text(delta,k);object(message,"message");if(!message.isMissingNode()&&!message.isNull())validateUsage(message.path("usage"));validateUsage(event.path("usage"));validateError(event.path("error"));String error=text(event.path("error"),"message");if(!error.isEmpty())throw new ModelClientException(endpoint.safe("API stream error: "+error));String answer="",reasoning="";List<ModelStreamAssembler.ToolDelta> fragments=new ArrayList<>();
            switch(type){case "message_start":if(!message.isMissingNode()&&!message.isNull())usage=AnthropicMessages.this.usage(message.path("usage"));break;case "content_block_start":if(block.isMissingNode()||block.isNull())break;switch(text(block,"type")){case "tool_use":String initial=source.raw("/content_block/input");if(initial.isEmpty()||initial.equals("null"))initial="{}";tools.put(index,new ToolState(text(block,"id"),text(block,"name"),initial));fragments.add(new ModelStreamAssembler.ToolDelta(toolIndex(index),text(block,"id"),"function",text(block,"name"),""));break;case "redacted_thinking":put(thought(index,"redacted_thinking"),"data",text(block,"data"));break;case "thinking":String value=text(block,"thinking");if(!value.isEmpty()){append(thought(index,"thinking"),"thinking",value);reasoning=value;}else thought(index,"thinking");break;case "text":answer=text(block,"text");break;}break;case "content_block_delta":if(delta.isMissingNode()||delta.isNull())break;switch(text(delta,"type")){case "text_delta":answer=text(delta,"text");break;case "thinking_delta":reasoning=text(delta,"thinking");append(thought(index,"thinking"),"thinking",reasoning);break;case "signature_delta":ObjectNode b=thought(index,"thinking");append(b,"signature",text(delta,"signature"));signature=b.path("signature").asText();break;case "input_json_delta":ToolState t=tools.get(index);if(t!=null){String json=text(delta,"partial_json");t.json.append(json);fragments.add(new ModelStreamAssembler.ToolDelta(toolIndex(index),"","","",json));}break;}break;case "content_block_stop":ToolState t=tools.get(index);if(t!=null){t.closed=true;if(t.json.isEmpty())fragments.add(new ModelStreamAssembler.ToolDelta(toolIndex(index),"","","",t.initial));}break;case "message_delta":String reason=text(delta,"stop_reason");if(!reason.isEmpty())stop=reason;if(event.hasNonNull("usage")){ObjectNode fresh=AnthropicMessages.this.usage(event.get("usage"));if(usage!=null){long prompt=Math.max(fresh.path("prompt_tokens").asLong(),usage.path("prompt_tokens").asLong()),read=Math.max(fresh.path("cache_read_tokens").asLong(),usage.path("cache_read_tokens").asLong()),write=Math.max(fresh.path("cache_write_tokens").asLong(),usage.path("cache_write_tokens").asLong());boolean reported=fresh.path("cache_reported").asBoolean()||usage.path("cache_reported").asBoolean();fresh=counters(prompt,fresh.path("completion_tokens").asLong(),read,write,Math.max(0,prompt-read),reported,false);}usage=fresh;}break;}
            if(!answer.isEmpty()||!reasoning.isEmpty()||!fragments.isEmpty())assembler.process(reasoning,answer,fragments,"");
        }
        void finish(ModelStreamAssembler assembler){ArrayNode calls=calls();assembler.replaceCalls(calls);assembler.signature(signature.isEmpty()?"":SIGNATURE+signature);ArrayNode blocks=JSON.createArrayNode();thoughts.values().forEach(b->blocks.add(b.deepCopy()));if(!blocks.isEmpty())assembler.reasoning(JSON.createObjectNode().set(BLOCKS,blocks));if(usage!=null)assembler.usage(usage);assembler.process("","",List.of(),AnthropicMessages.finish(stop,calls.size(),incomplete()));assembler.end();}
    }
    private static void append(ObjectNode obj,String key,String value){String combined=obj.path(key).asText()+value;if(!combined.isEmpty())obj.put(key,combined);}
    private static String line(InputStream input)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();while(true){int c=input.read();if(c<0){if(bytes.size()==0)return null;break;}if(c=='\n')break;if(bytes.size()>=1<<20)throw new ModelClientException("Stream line exceeds Go SSE maximum size");bytes.write(c);}byte[] raw=bytes.toByteArray();int length=raw.length;if(length>0&&raw[length-1]=='\r')length--;return GoUtf8.decode(Arrays.copyOf(raw,length));}
    private void process(CallContext context,InputStream body,Consumer<ObjectNode> consumer){ModelStreamAssembler assembler=new ModelStreamAssembler(context,consumer,endpoint);StreamState state=new StreamState();try{while(true){context.check();String raw=line(body);if(raw==null){state.finish(assembler);return;}if(!raw.startsWith("data:"))continue;String data=raw.substring(5);if(data.startsWith(" "))data=data.substring(1);if(ModelText.trim(data).equals("[DONE]")){state.finish(assembler);return;}if(data.isEmpty())continue;ModelJsonSource source;try{source=new ModelJsonSource(data,true);}catch(IOException ex){throw new ModelClientException("decode SSE response: "+ex.getMessage());}state.consume(source,assembler);if(text(source.root,"type").equals("message_stop")){state.finish(assembler);return;}}}catch(CancellationException ex){throw ex;}catch(IOException|ModelClientException ex){context.check();assembler.fail(ex.getMessage());}}
    private ObjectNode collect(CallContext call,InputStream body){ObjectNode result=JSON.createObjectNode().put("content","");result.set("usage",JSON.createObjectNode().put("prompt_tokens",0).put("completion_tokens",0).put("total_tokens",0).put("cache_reported",false));StringBuilder content=new StringBuilder(),reasoning=new StringBuilder();process(call,body,event->{switch(event.path("response_type").asText()){case "error":throw new StreamCollectionFailure(event.path("content").asText());case "thinking":reasoning.append(event.path("content").asText());break;case "answer":content.append(event.path("content").asText());if(!event.path("tool_calls").isEmpty())result.set("tool_calls",event.get("tool_calls").deepCopy());if(event.hasNonNull("usage"))result.set("usage",event.get("usage").deepCopy());if(!event.path("finish_reason").asText().isEmpty())result.put("finish_reason",event.path("finish_reason").asText());if(event.path("data").hasNonNull("reasoning_signature"))result.set("reasoning_signature",event.path("data").get("reasoning_signature").deepCopy());if(event.path("data").hasNonNull("reasoning_metadata"))result.set("reasoning_metadata",event.path("data").get("reasoning_metadata").deepCopy());break;}});result.put("content",content.toString());put(result,"reasoning_content",reasoning.toString());return result;}
    private static final class StreamCollectionFailure extends ModelClientException {StreamCollectionFailure(String message){super(message);}}
}
